"""一个有缺陷的计算器模块，用于演示 repair 模式"""
import math


class Calculator:
    """一个简单的计算器，包含多个缺陷"""

    def add(self, a, b):
        return a + b

    def subtract(self, a, b):
        return a - b

    def multiply(self, a, b):
        return a * b

    def divide(self, a, b):
        return a / b  # Bug: 未处理除零

    def factorial(self, n):
        if n == 0:
            return 1
        return n * self.factorial(n - 1)  # Bug: 负数没有处理

    def sqrt(self, x):
        return math.sqrt(x)  # Bug: 负数没有处理

    def power(self, base, exp):
        result = 1
        for _ in range(exp):
            result *= base
        return result  # Bug: 指数为负数时无限循环


class StringCalculator:
    """字符串表达式计算器"""

    def calculate(self, expression):
        """计算简单表达式如 '1+2', '3*4' """
        if '+' in expression:
            parts = expression.split('+')
            return int(parts[0]) + int(parts[1])
        elif '-' in expression:
            parts = expression.split('-')
            return int(parts[0]) - int(parts[1])
        # Bug: 缺少乘法和除法处理
        return None  # Bug: 应该抛出异常而不是返回None


